BEGIN;
CREATE TABLE IF NOT EXISTS finance_audits(id BIGSERIAL PRIMARY KEY,audit_reference TEXT NOT NULL UNIQUE,audit_type VARCHAR(25) NOT NULL,auditor_organisation TEXT,scope TEXT NOT NULL,period_start DATE,period_end DATE,owner_user_id BIGINT,due_at TIMESTAMPTZ,status VARCHAR(30) NOT NULL DEFAULT 'open',external_auditors_on_site BOOLEAN NOT NULL DEFAULT FALSE,boardroom_booking_id BIGINT,created_by BIGINT NOT NULL,updated_by BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS finance_audit_items(id BIGSERIAL PRIMARY KEY,audit_id BIGINT NOT NULL REFERENCES finance_audits(id) ON DELETE CASCADE,item_type VARCHAR(30) NOT NULL,title TEXT NOT NULL,description TEXT,owner_user_id BIGINT,due_at TIMESTAMPTZ,status VARCHAR(30) NOT NULL DEFAULT 'open',management_response TEXT,corrective_action TEXT,closed_at TIMESTAMPTZ,created_by BIGINT NOT NULL,updated_by BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS finance_evidence_register(id BIGSERIAL PRIMARY KEY,evidence_reference TEXT NOT NULL UNIQUE,title TEXT NOT NULL,classification VARCHAR(40) NOT NULL,record_type VARCHAR(40),record_id BIGINT,sharepoint_url TEXT,attachment_id BIGINT,version_number INTEGER NOT NULL DEFAULT 1,review_status VARCHAR(25) NOT NULL DEFAULT 'pending',supersedes_id BIGINT,uploaded_by BIGINT NOT NULL,reviewed_by BIGINT,uploaded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),reviewed_at TIMESTAMPTZ,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS finance_notifications(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL,event_type VARCHAR(50) NOT NULL,title TEXT NOT NULL,message TEXT,record_type VARCHAR(40),record_id BIGINT,priority VARCHAR(20) NOT NULL DEFAULT 'normal',read_at TIMESTAMPTZ,action_required BOOLEAN NOT NULL DEFAULT FALSE,action_status VARCHAR(25) NOT NULL DEFAULT 'pending',due_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS finance_access_requests(id BIGSERIAL PRIMARY KEY,request_reference TEXT NOT NULL UNIQUE,requester_user_id BIGINT NOT NULL,target_user_id BIGINT NOT NULL,requested_access TEXT NOT NULL,business_reason TEXT NOT NULL,status VARCHAR(25) NOT NULL DEFAULT 'pending_manager',manager_user_id BIGINT,manager_decision_at TIMESTAMPTZ,manager_reason TEXT,admin_override BOOLEAN NOT NULL DEFAULT FALSE,override_by BIGINT,override_reason TEXT,grant_source VARCHAR(30),granted_at TIMESTAMPTZ,revoked_at TIMESTAMPTZ,revoked_by BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS finance_governance_actions(id BIGSERIAL PRIMARY KEY,record_type VARCHAR(40) NOT NULL,record_id BIGINT NOT NULL,action VARCHAR(40) NOT NULL,actor_user_id BIGINT NOT NULL,reason TEXT,detail JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ix_finance_audits_status_due ON finance_audits(status,due_at);
CREATE INDEX IF NOT EXISTS ix_finance_evidence_record ON finance_evidence_register(record_type,record_id,active);
CREATE INDEX IF NOT EXISTS ix_finance_notifications_user ON finance_notifications(user_id,read_at,action_status);
CREATE INDEX IF NOT EXISTS ix_finance_access_status ON finance_access_requests(status,created_at DESC);
COMMIT;
